{"chunk_id":"65ab0b","wall_time_seconds":0.000004072,"exit_code":0,"original_token_count":1129,"output":"#!/usr/bin/env python3
import bz2
import gzip
import os
import sys
import zlib
import unix_compress

VERSION = """Ancient v2.3.0
Copyright (C) Teemu Suutari

Usage: ancient i[dentify] packed_input_files...
 - identifies compression used in a file(s)
Usage: ancient v[erify] packed_input_file unpacked_comparison_file
 - verifies decompression against known good unpacked file
Usage: ancient [-p] d[ecompress] packed_input_file output_file
 - decompresses single file
 - use p-flag to preserve timestamp of the original"""


def fail(s):
    print(s)
    return 255


def decode(data):
    if data.startswith(b"\x1f\x8b"):
        remaining = data
        first = None
        while remaining:
            dec = zlib.decompressobj(31)
            part = dec.decompress(remaining) + dec.flush()
            if not dec.eof:
                raise ValueError
            if first is None:
                first = part
            remaining = dec.unused_data
        if first is None or not first:
            raise ValueError
        return "gzip: Deflate", first
    if data.startswith(b"BZh"):
        dec = bz2.BZ2Decompressor()
        return "bz2: bzip2", dec.decompress(data)
    if data.startswith(b"\x1f\x9d"):
        return "compress: LZW", unix_compress.decompress(data)
    # zlib streams are used by a few modern containers
    if len(data) >= 2 and data[0] == 0x78 and ((data[0] << 8) + data[1]) % 31 == 0:
        return "zlib: Deflate", zlib.decompress(data)
    raise ValueError


def main(argv):
    preserve = False
    if argv and argv[0] == "-p":
        preserve = True
        argv = argv[1:]
    if not argv:
        print(VERSION)
        return 255
    cmd = argv[0]
    if cmd.startswith("identify") or cmd == "i":
        if len(argv) < 2:
            print(VERSION)
            return 255
        rc = 0
        for path in argv[1:]:
            try:
                data = open(path, "rb").read()
            except OSError:
                rc = fail("Could not read file " + path)
                continue
            try:
                if data.startswith(b"\x1f\x1e"):
                    name = "z: Pack"
                elif data.startswith(b"\x1f\xa0") and len(data) >= 4:
                    name = "SCO Compress LZH"
                elif data.startswith(b"BZh") and len(data) >= 4 and data[3:4] in b"123456789":
                    name = "bz2: bzip2"
                else:
                    name, _ = decode(data)
                print(f"Compression of {path} is {name}")
            except Exception:
                print(f"Unknown or invalid compression format in file {path}")
        return rc
    if cmd.startswith("verify") or cmd == "v":
        if len(argv) != 3:
            print(VERSION)
            return 255
        packed, expected = argv[1:]
        try:
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            reference = open(expected, "rb").read()
        except OSError:
            return fail("Could not read file " + expected)
        try:
            _, result = decode(src)
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        if len(result) != len(reference):
            return fail(f"Verify failed for {packed} and {expected} - sizes differ")
        if result != reference:
            index = next(i for i, (a, b) in enumerate(zip(result, reference)) if a != b)
            return fail(f"Verify failed for {packed} and {expected} - contents differ @ {index}")
        print("Files match!")
        return 0
    if cmd.startswith("decompress") or cmd == "d":
        if len(argv) != 3:
            print(VERSION)
            return 255
        packed, output = argv[1:]
        try:
            st = os.stat(packed)
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            _, result = decode(src)
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        try:
            with open(output, "wb") as f:
                f.write(result)
            if preserve:
                os.utime(output, (st.st_atime, st.st_mtime))
        except OSError:
            print("Could not write file " + output)
        return 0
    print("Unknown command")
    print(VERSION)
    return 255


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"}

