"""Decoder for the traditional Unix compress (.Z) stream format."""

class CompressError(ValueError):
    pass


def decompress(data: bytes) -> bytes:
    if len(data) < 3 or data[:2] != b"\x1f\x9d":
        raise CompressError("invalid compress header")
    flags = data[2]
    maxbits = flags & 0x1f
    block_mode = bool(flags & 0x80)
    if flags & 0x60 or not 9 <= maxbits <= 16:
        raise CompressError("invalid compress header")
    src = data[3:]
    pos = 0
    width = 9
    maxcode = (1 << width) - 1
    maxmax = 1 << maxbits
    clear = 256
    next_code = 257 if block_mode else 256
    table = {i: bytes((i,)) for i in range(256)}
    out = bytearray()
    old = None
    group_count = 0
    leading_clear_seen = False

    def get_code():
        nonlocal pos, width, maxcode, group_count
        if group_count == 8:
            group_count = 0
            if next_code > maxcode and width < maxbits:
                width += 1
                maxcode = (1 << width) - 1
        bit = pos
        if bit + width > len(src) * 8:
            return None
        value = int.from_bytes(src[bit // 8:(bit + width + 7) // 8], "little")
        code = (value >> (bit & 7)) & ((1 << width) - 1)
        pos += width
        group_count += 1
        return code

    while True:
        code = get_code()
        if code is None:
            break
        if block_mode and code == clear:
            if old is None:
                # One leading CLEAR is accepted and exposes the zero-initialized
                # previous phrase; it does not discard the following code.
                if leading_clear_seen:
                    raise CompressError("unexpected clear code")
                leading_clear_seen = True
                out.append(0)
            else:
                # A normal table reset discards the remainder of this packing
                # group before codes resume at the next group boundary.
                skipped_bits = (8 - group_count) * width
                if pos + skipped_bits > len(src) * 8:
                    raise CompressError("truncated clear group")
                pos += skipped_bits
                group_count = 0
            table = {i: bytes((i,)) for i in range(256)}
            next_code = 257
            old = None
            width = 9
            maxcode = (1 << width) - 1
            continue
        # At the minimum code width Ancient rejects further codes once the
        # dictionary is full; wider streams keep using the frozen table.
        if maxbits == 9 and next_code >= maxmax and old is not None:
            raise CompressError("dictionary full")
        if code in table:
            entry = table[code]
        elif old is not None:
            # Ancient tolerates unknown codewords after the first entry by
            # applying the same KwKwK expansion used for the next code.
            entry = old + old[:1]
        else:
            raise CompressError("invalid compress code")
        out.extend(entry)
        if old is not None and next_code < maxmax:
            table[next_code] = old + entry[:1]
            next_code += 1
        old = entry
    return bytes(out)
